<?php
if(PHP_SAPI!=='cli')exit;$_SERVER['HTTP_HOST']='127.0.0.1:8095';$_SERVER['REQUEST_URI']='/';require __DIR__.'/.runtime/wordpress/wp-load.php';require_once ABSPATH.'wp-admin/includes/plugin.php';
$n=0;function pu($v,$s){global $n;if(!$v)throw new RuntimeException($s);$n++;echo "PASS $s\n";}
$meta=json_decode(file_get_contents(dirname(__DIR__).'/release/plugin.json'),true);$remote=$meta;$response=null;$requests=0;
